const ICONS_256 = RAW_ICONS.map(([id, name, label, theme, path]) => ({
    id,
    name,
    label,
    theme,
    path,
    svg: path
}));

const ICONS_MAP = new Map(ICONS_256.map(ic => [ic.name.toLowerCase(), ic]));

function getIcon(opcodeOrName) {
    if (typeof opcodeOrName === 'number') {
        const idx = opcodeOrName & 0xFF;
        return ICONS_256[idx] || ICONS_256[0];
    }
    const key = String(opcodeOrName || '').toLowerCase().trim();
    return ICONS_MAP.get(key) || ICONS_256[0];
}

module.exports = {
    ICONS_256,
    RAW_ICONS,
    getIcon
};
